import{_ as t,o,c as s,a0 as a}from"./chunks/framework.ChlVJx0I.js";const u=JSON.parse('{"title":"The vendored antislop copy is edited for a tracked tree","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0034-the-vendored-antislop-copy-is-edited-for-a-tracked-tree.md","filePath":"adr/0034-the-vendored-antislop-copy-is-edited-for-a-tracked-tree.md","lastUpdated":1791406510000}'),n={name:"adr/0034-the-vendored-antislop-copy-is-edited-for-a-tracked-tree.md"};function i(r,e,d,l,c,h){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="the-vendored-antislop-copy-is-edited-for-a-tracked-tree" tabindex="-1">The vendored antislop copy is edited for a tracked tree <a class="header-anchor" href="#the-vendored-antislop-copy-is-edited-for-a-tracked-tree" aria-label="Permalink to &quot;The vendored antislop copy is edited for a tracked tree&quot;">​</a></h1><p>antislop (<code>miqdadbadjuber/Anti-Slop</code>, MIT) becomes the second Skill source under ADR-0013: six skills mirrored under <code>skills/anti-slop/</code>, one Source pin, three-way merge on every skill sync. Its core <code>SKILL.md</code> opens with a First-Run Install Wizard that tells the agent to fetch the missing skill folders and append an antislop pointer block to the project&#39;s entry file, and it carries an update section pointing at <code>npx antislop-ai --update</code>, <code>npx skills update</code>, and seven plugin commands. Read inside a tracked tree those instructions are wrong, and one is destructive: <code>--update</code> replaces every antislop folder wholesale, which bypasses the three-way merge and discards Local tweaks, and the pointer block writes into the operator&#39;s <code>AGENTS.md</code> for skills pi already loads. The same file&#39;s mode resolution ends the turn to ask &quot;during or after?&quot; whenever no preference exists, which stalls an unattended session. We decided: edit the local copy in place, in exactly two places, and leave every other byte identical to upstream.</p><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>Keep the copy byte-identical to upstream.</strong> Rejected: the copy then instructs every session that loads it to write into the project&#39;s entry file and to run an updater that overwrites the tracked copies. That is not a cosmetic mismatch; it fights the tracking model ADR-0013 rests on.</li><li><strong>Ship a settings file along with the skills.</strong> Rejected: the skill reads only the platform path (<code>~/.config/antislop/settings.json</code>, or <code>%APPDATA%\\antislop\\settings.json</code> on Windows), shared across agents and projects and independent of install location. A file inside the Skill tree is never read by anything.</li><li><strong>Write that global settings file on the operator&#39;s machine.</strong> Rejected: it is per-machine invisible state, absent on a fresh install and in CI, and it would have our package write a third party&#39;s global config unprompted.</li><li><strong>Leave the mode question and accept the stall.</strong> Rejected: the skill says to end the response and wait for the answer &quot;before any UI review, planning, or concept, even for read-only requests&quot;, and the factory runs cycles with no human in the terminal.</li><li><strong>Also rewrite <code>${CLAUDE_SKILL_DIR}</code> in <code>antislop-human</code>.</strong> Rejected: upstream already says to point the script path at the skill&#39;s own folder when that variable is absent, and pi&#39;s prompt resolves relative paths against the skill directory. The command degrades correctly on its own, and every byte left unchanged merges clean on the next sync.</li><li><strong>Ask upstream to gate the install wizard per loader.</strong> Deferred: upstream has no way to know that a loader tracks the copy rather than installing it by folder, so the cut is ours to own. If upstream ever gates it, the sync brings the gate back as a conflict to resolve by taking theirs.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The divergence is one file, two places: the core&#39;s <code>## First-Run Install Wizard</code> and <code>### Already installed, and the user asks how to update</code> sections are cut, and step 3 of <code>## Two Usage Modes</code> resolves an unresolved mode to <code>during</code> with the notice <code>antislop active: during (package default).</code> instead of asking, which retires the question block below it. Nothing outside the cut sections refers to them, so the cut leaves no dangling text.</li><li>Steps 1 and 2 of the mode ladder stay upstream&#39;s: an explicit session instruction, then the global settings file. An operator who wants <code>after</code> as a machine default still gets it the upstream way, with <code>npx antislop-ai --mode after</code>, and an operator who wants it for one session just says so.</li><li>The other five skills stay byte-identical, as does everything the sync carries: the frontmatter (<code>allowed-tools</code> is unknown to pi and ignored; <code>disable-model-invocation</code> is not set, so all six stay model-invocable), and the extra files inside the skill folders (<code>VERSION</code>, <code>contrast-check.py</code>, <code>contrast-mcp.py</code>). Deleting the unused MCP server would stick only until upstream edits that file, and would cost a conflict.</li><li>An upstream change to a cut region surfaces as a conflict in <code>skills:update</code>, with this ADR as the reason, and the Source pin holds until it is resolved.</li><li>The upstream <code>LICENSE</code> at the source root is copied by hand at adoption: the skill sync ignores files that sit outside a skill directory.</li></ul>',6)])])}const f=t(n,[["render",i]]);export{u as __pageData,f as default};
